import {previewPlan} from './tag-editor-plan.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),clone=v=>structuredClone(v);
const S={artists:[],albums:[],artist:null,album:null,original:[],draft:[],selected:new Set(),focus:null,mode:'from',plan:null,revision:0,cache:new Map(),renames:{},imported:false,sourceMode:'DEMO'};
let timer,requestSeq=0,artistRequest=0,albumRequest=0;
const fields={title:'TITLE',artist:'ARTIST',featuring:'FEATURING',genre:'GENRE',tracknumber:'TRACKNUMBER',discnumber:'DISCNUMBER',album:'ALBUM',album_artist:'ALBUMARTIST',date:'DATE'};
const values=(e,f)=>(e.tags[f]||[]).join(' | '),basename=f=>f.split('/').pop(),number=e=>parseInt(values(e,'tracknumber'),10),disc=e=>parseInt(values(e,'discnumber'),10)||1;
const padded=e=>number(e)>0&&number(e)<=99?String(number(e)).padStart(2,'0'):'';
const changed=e=>JSON.stringify(e.tags)!==JSON.stringify(S.original.find(x=>x.file===e.file)?.tags)||!!S.renames[e.file];
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
const pending=new Map();let rpcSeq=0,channel=null;
function read(url){return new Promise((resolve,reject)=>{const id=++rpcSeq,t=setTimeout(()=>{pending.delete(id);reject(Error('NAS 조회 시간이 초과되었습니다.'));},25000);pending.set(id,{resolve,reject,t});parent.postMessage({type:'vr-tag-read',id,channel,url},location.origin);});}
async function api(url,body){if(!channel)throw Error('관리자 인증 연결이 필요합니다.');if(url==='/api/preview')return previewPlan(body);return read(url);}
window.addEventListener('message',event=>{if(event.source!==parent||event.origin!==location.origin)return;const m=event.data;if(m?.type==='vr-tag-init'&&!channel&&typeof m.channel==='string'){channel=m.channel;document.body.hidden=false;start();}if(m?.type==='vr-tag-revoke'){channel=null;S.cache.clear();S.original=[];S.draft=[];document.body.className='locked';document.querySelector('.shell').remove();}if(m?.type==='vr-tag-result'&&m.channel===channel){const p=pending.get(m.id);if(p){clearTimeout(p.t);pending.delete(m.id);m.error?p.reject(Error(m.error)):p.resolve(m.result);}}});
if(parent===window){document.body.hidden=false;document.body.classList.add('locked');}
parent.postMessage({type:'vr-tag-ready'},location.origin);

function cover(a,size=''){return `<span class="cover ${size}" style="--accent:${esc(a.accent||'#7e8a8f')}"><img data-tag-cover="${esc(a.id)}" alt="${esc(a.title)} 커버"><span>${esc(a.title.slice(0,2).toUpperCase())}</span></span>`}
function save(){if(S.album)S.cache.set(S.album.id,{draft:clone(S.draft),renames:clone(S.renames)})}
function route(){const home=location.hash==='#admin';$('#adminHome').hidden=!home;$('#editor').hidden=home;$('#adminLink').classList.toggle('active',home)}window.addEventListener('hashchange',route);route();
async function loadArtists(){try{let data=await api('/api/artists?q='+encodeURIComponent($('#artistSearch').value));S.artists=data.items;$('#artistCount').textContent=`${data.items.length}명`;$('#artistList').innerHTML=data.items.map(a=>`<button class="artist-row ${S.artist?.id===a.id?'active':''}" data-artist="${esc(a.id)}"><span class="avatar">${esc(a.name.slice(0,2))}</span><span><strong>${esc(a.name)}</strong><small>${esc(a.folder)}</small></span><span class="count">${a.albums??''}</span></button>`).join('')||'<p class="browser-note">검색 결과가 없습니다.</p>';if(data.truncated)toast('현재 조회 범위만 표시합니다. 검색어를 구체화하세요.')}catch(e){toast(e.message)}}
async function selectArtist(id){const request=++artistRequest;save();const a=S.artists.find(x=>x.id===id);if(!a)return;S.artist=a;const data=await api('/api/albums?artist='+encodeURIComponent(id));if(request!==artistRequest)return;S.albums=data.items;$('#albumListTitle').textContent=a.name+' · 앨범';$('#albumCount').textContent=`${data.items.length}장`;renderAlbums();document.querySelectorAll('[data-artist]').forEach(b=>b.classList.toggle('active',b.dataset.artist===id));if(data.items.length)await selectAlbum(data.items[0].id)}
function covers(){parent.postMessage({type:'vr-tag-covers',channel},location.origin)}
function renderAlbums(){$('#albumList').innerHTML=S.albums.map(a=>`<button class="album-card ${S.album?.id===a.id?'active':''}" data-album="${esc(a.id)}">${cover(a)}<span><strong>${esc(a.title)}</strong><small>${esc(a.date)}${a.count!=null?' · '+a.count+'곡':''} · ${'NAS 색인'}</small></span></button>`).join('');covers()}
async function selectAlbum(id){const request=++albumRequest;save();try{let {album}=await api('/api/tracks?album='+encodeURIComponent(id));if(request!==albumRequest)return;S.imported=false;useAlbum(album);renderAlbums()}catch(e){toast(e.message)}}
function useAlbum(album){S.album=album;S.original=clone(album.entries);const saved=S.cache.get(album.id);S.draft=clone(saved?.draft||album.entries);S.renames=clone(saved?.renames||{});S.selected=new Set(S.draft.map(e=>e.file));S.focus=S.draft[0]?.file;S.revision++;$('#albumHeader').innerHTML=`${cover(album)}<div><h2>${esc(album.title)}</h2><p>${esc(album.artist)} · ${esc(album.date)} · ${'NAS 색인 태그 · 파일 재읽기 아님'}</p><div class="folder-path" title="${esc(album.path)}">${esc(album.path)}</div></div>`;renderCommon();renderTracks();schedule();covers()}
function renderCommon(){let warnings=[];$('#commonFields').innerHTML=['album','album_artist','date'].map(f=>{const all=[...new Set(S.draft.map(e=>values(e,f)))],mixed=all.length>1;if(mixed)warnings.push(fields[f]);return `<label class="${mixed?'mixed':''}">${fields[f]}<input data-common="${f}" aria-label="앨범 공통 ${fields[f]}" value="${mixed?'':esc(all[0]||'')}" placeholder="${mixed?'파일마다 값이 다름 · 변경 없음':'빈 태그'}">${mixed?`<small>불일치: ${all.map(esc).join(' / ')}</small>`:''}</label>`}).join('');$('#commonWarning').textContent=warnings.length?`${warnings.join(', ')} 값이 파일마다 다릅니다. 직접 입력하기 전까지 원본을 유지합니다.`:''}
function renderTracks(){let lastDisc=null,html='';const filtered=S.draft.filter(e=>!$('#missingOnly').checked||changed(e)||!(e.tags.title||[]).length||!padded(e));for(const e of filtered){const d=disc(e);if(lastDisc!==d){html+=`<tr class="disc-row"><td colspan="8">DISC ${String(d).padStart(2,'0')}</td></tr>`;lastDisc=d}const missing=!e.tags.title?.length||!padded(e);html+=`<tr class="${S.selected.has(e.file)?'selected ':''}${S.focus===e.file?'focused':''}" data-file="${esc(e.file)}"><td><input type="checkbox" data-select="${esc(e.file)}" aria-label="${esc(basename(e.file))} 선택" ${S.selected.has(e.file)?'checked':''}></td><td><button class="filename" data-path="${esc(e.file)}" title="${esc(e.file)}">${esc(basename(e.file))}</button><span class="file-ext">${S.renames[e.file]?'예정: '+esc(S.renames[e.file]):esc(basename(e.file).split('.').pop().toUpperCase())+' · 경로 확인'}</span></td><td><input data-field="tracknumber" data-id="${esc(e.file)}" aria-label="트랙번호 ${esc(basename(e.file))}" value="${padded(e)}" placeholder="없음" inputmode="numeric"></td>${['title','artist','featuring','genre'].map(f=>`<td><input data-field="${f}" data-id="${esc(e.file)}" aria-label="${fields[f]} ${esc(basename(e.file))}" value="${esc(values(e,f))}" placeholder="${f==='title'?'제목 없음':'—'}" title="${esc(values(e,f))}">${f==='title'&&!e.tags.title?.length?'<span class="state missing">제목 없음</span>':''}</td>`).join('')}<td><span class="state ${changed(e)?'draft':missing?'missing':''}">${changed(e)?'변경 초안':missing?'누락':'정상'}</span></td></tr>`}$('#trackCount').textContent=`${S.draft.length}곡`;$('#track-panel')?.setAttribute('data-count',S.draft.length);$('#selectedCount').textContent=`${S.selected.size} / ${S.draft.length}곡 선택`;$('#selectAll').checked=S.selected.size===S.draft.length;$('#selectAll').indeterminate=S.selected.size>0&&S.selected.size<S.draft.length;$('tbody')?.remove();$('#editor table').insertAdjacentHTML('beforeend','<tbody>'+html+'</tbody>');renderCompare()}
function renderCompare(){const e=S.draft.find(x=>x.file===S.focus),before=S.original.find(x=>x.file===S.focus);if(!e)return;let diff=Object.keys(fields).filter(f=>values(before,f)!==values(e,f));$('#track-panel');let box=$('.compare');if(!box){box=document.createElement('div');box.className='compare';$('.track-panel').append(box)}box.innerHTML=`<strong>${esc(basename(e.file))}</strong><div class="compare-values">${diff.length?diff.map(f=>`<span>${fields[f]} <del>${esc(values(before,f)||'빈 값')}</del><b>${esc(values(e,f)||'빈 값')}</b></span>`).join(''):'원본과 초안이 같습니다. 트랙의 값을 편집하거나 아래 변환 결과를 확인하세요.'}</div>`}
function schedule(){requestSeq++;S.plan=null;$('#applyDraft').disabled=true;clearTimeout(schedule.id);schedule.id=setTimeout(preview,180)}
async function preview(){clearTimeout(schedule.id);const seq=++requestSeq;if(!S.album)return;if(!S.selected.size){$('#preview').innerHTML='';$('#planStatus').textContent='미리보기할 트랙을 선택하세요.';return}$('#planStatus').textContent='기존 변환 엔진으로 계산 중…';try{const r=await api('/api/preview',{album:{id:S.album.id,artist:S.album.artist,title:S.album.title,path:S.album.path},entries:S.draft,selected:[...S.selected],mode:S.mode,format:$('#format').value,replace:$('#replace').checked});if(seq!==requestSeq)return;S.plan=r;renderPreview()}catch(e){if(seq!==requestSeq)return;$('#planStatus').textContent=e.message;$('#preview').innerHTML='<div class="preview-row"><span class="error">형식 또는 입력을 확인하세요.</span></div>';S.plan=null}}
const reasons={filename_does_not_match_format:'파일명과 형식 문자열이 맞지 않음',ambiguous_filename_format:'구분자가 모호해 추출값을 확정할 수 없음',existing_value_preserved:'기존값 보존',joint_artist_backslash_protected:'공동 아티스트 A\\B 보호',destination_is_unselected_track:'선택하지 않은 파일과 이름 충돌',duplicate_rename_target:'변경 예정 파일명 중복',destination_currently_exists:'기존 파일명과 충돌',duplicate_track_number_on_disc:'디스크 내 트랙번호 중복',missing_or_invalid_tracknumber:'트랙번호가 없거나 잘못됨',missing_tag_for_format_title:'TITLE 태그 없음'};
function reason(s){return reasons[s]||String(s||'').replace('missing_tag_for_format:title','TITLE 태그 없음').replace('unsafe_filename_characters','파일명에 사용할 수 없는 문자').replace('album_common_editor_only','앨범 공통 편집에서만 변경').replace('use_normalize_tracknumbers_for_existing_format','기존 번호는 두 자리 정규화로 변경')}
function changesFor(row){if(row.changes)return row.changes;if(S.mode==='normalize'&&row.after){const before=S.draft.find(e=>e.file===row.file)?.tags.tracknumber||[];return JSON.stringify(before)!==JSON.stringify(row.after)?{tracknumber:{before,after:row.after}}:{}}return {}}
function renderPreview(){const p=S.plan,rows=p.rows||[];let held=0,proposed=0;$('#preview').innerHTML=rows.map(row=>{const changes=changesFor(row),changeKeys=Object.keys(changes),bad=row.state==='HOLD'||row.state==='UNPARSED',hasRename=!!row.suggested_file_name&&row.state==='RENAME_PROPOSED';if(bad)held++;if(!bad&&(changeKeys.length||hasRename))proposed++;let content=changeKeys.map(f=>`<div>${esc(fields[f]||f)} <del>${esc(changes[f].before.join(' | ')||'빈 값')}</del> <span class="proposed">${esc(changes[f].after.join(' | '))}</span></div>`).join('');if(row.suggested_file_name)content=`<del>${esc(row.current_file_name||basename(row.file))}</del><div class="proposed">${esc(row.suggested_file_name)}</div>`;if(!content)content=row.parsed_fields?Object.entries(row.parsed_fields).map(([f,v])=>`${fields[f]||f}: ${esc(v.join(' | '))}`).join(' · '):'변경 없음';if(row.discarded_dummy_parts?.length)content+=`<div><small>DUMMY ${row.discarded_dummy_parts.map(esc).join(' / ')} · 저장하지 않음</small></div>`;if(Object.keys(row.skipped||{}).length)content+=`<div><small>${[...new Set(Object.values(row.skipped))].map(x=>esc(reason(x))).join(' · ')}</small></div>`;if(bad)content+=`<div class="error">${esc(reason(row.reason))}</div>`;return `<div class="preview-row"><div>${esc(basename(row.file))}</div><div>${content}</div><div class="${bad?'error':'proposed'}">${bad?'확인 필요':changeKeys.length||hasRename?'변경 제안':'기존값 유지'}</div></div>`}).join('')||`<div class="preview-row"><span class="error">${esc(reason(p.reason)||'표시할 결과 없음')}</span></div>`;$('#planStatus').textContent=`선택 ${S.selected.size}곡 · 변경 제안 ${proposed}곡 · 확인 필요 ${held}곡${p.reason?' · '+reason(p.reason):''}`;$('#applyDraft').disabled=!proposed;$('#applyDraft').textContent=`${proposed||'선택'}곡 결과를 초안에 반영`}
function applyDraft(){if(!S.plan)return;let count=0;for(const row of S.plan.rows||[]){if(['HOLD','UNPARSED'].includes(row.state)||!S.selected.has(row.file))continue;const e=S.draft.find(x=>x.file===row.file);if(!e)continue;const changes=changesFor(row);if(Object.keys(changes).length){for(const [f,c] of Object.entries(changes))e.tags[f]=clone(c.after);count++}if(row.suggested_file_name&&row.state==='RENAME_PROPOSED'){S.renames[row.file]=row.suggested_file_name;count++}}save();renderCommon();renderTracks();schedule();toast(`${count}곡을 임시 초안에 반영했습니다. 원본은 변경하지 않았습니다.`)}
$('#artistList').addEventListener('click',e=>{let b=e.target.closest('[data-artist]');if(b)void selectArtist(b.dataset.artist).catch(e=>toast(e.message))});$('#albumList').addEventListener('click',e=>{let b=e.target.closest('[data-album]');if(b)selectAlbum(b.dataset.album)});$('#artistSearch').addEventListener('keydown',e=>{if(e.key==='Enter')void loadArtists()});
$('.track-panel').addEventListener('click',e=>{const p=e.target.closest('[data-path]');if(p){$('#fullPath').textContent=p.dataset.path;$('#pathDialog').showModal();return}const row=e.target.closest('tr[data-file]');if(row){S.focus=row.dataset.file;renderCompare()}});
$('.track-panel').addEventListener('change',e=>{if(e.target.dataset.select){let f=e.target.dataset.select;e.target.checked?S.selected.add(f):S.selected.delete(f);renderTracks();schedule()}if(e.target.dataset.field){const f=e.target.dataset.field,entry=S.draft.find(x=>x.file===e.target.dataset.id);if(!entry)return;let v=e.target.value.trim();if(f==='tracknumber'&&v&&!/^([1-9]|[1-9]\d|0[1-9])(\/\d+)?$/.test(v)){toast('트랙번호는 01~99 범위로 입력하세요.');renderTracks();return}if(f==='artist'&&(entry.tags.artist||[]).some(v=>v.includes('\\'))&&v!==values(entry,f)){toast('공동 아티스트 A\\B는 이 시험판에서 자동 변경하지 않습니다.');renderTracks();return}entry.tags[f]=v?v.split(' | ').map(x=>x.trim()).filter(Boolean):[];S.focus=entry.file;save();renderTracks();schedule()}});
$('#selectAll').addEventListener('change',e=>{S.selected=new Set(e.target.checked?S.draft.map(x=>x.file):[]);renderTracks();schedule()});$('#missingOnly').addEventListener('change',renderTracks);$('#closePath').onclick=()=>$('#pathDialog').close();
$('#commonFields').addEventListener('change',e=>{const f=e.target.dataset.common;if(!f)return;const v=e.target.value.trim();for(const row of S.draft)row.tags[f]=v?[v]:[];save();renderCommon();renderTracks();schedule();toast(`앨범 ${S.draft.length}곡의 공통 태그 초안만 변경했습니다.`)});
$('.mode-tabs').addEventListener('click',e=>{let i=[...$('.mode-tabs').children].indexOf(e.target);if(i<0)return;S.mode=['from','to','number','normalize'][i];[...$('.mode-tabs').children].forEach((b,n)=>b.classList.toggle('active',i===n));$('#formatArea').hidden=i>1;$('#numberHelp').hidden=i<2;if(S.mode==='to'&&$('#format').value.includes('%dummy%'))$('#format').value='%discnumber%-%track% %title%';schedule()});
$('#format').addEventListener('input',schedule);$('#replace').addEventListener('change',schedule);$('#preset').addEventListener('change',e=>{if(e.target.value){$('#format').value=e.target.value;schedule()}});$('#variable').innerHTML+=[ 'artist','albumartist','album','date','year','discnumber','track','title','genre','featuring','dummy'].map(x=>`<option value="%${x}%">%${x}%</option>`).join('');$('#variable').addEventListener('change',e=>{let input=$('#format'),start=input.selectionStart??input.value.length,end=input.selectionEnd??start;input.setRangeText(e.target.value,start,end,'end');input.focus();e.target.value='';schedule()});$('#refreshBtn').onclick=preview;$('#applyDraft').onclick=applyDraft;
$('#resetBtn').onclick=()=>{S.draft=clone(S.original);S.renames={};save();renderCommon();renderTracks();schedule();toast('현재 앨범의 임시 초안을 초기화했습니다.')};
async function browse(path=''){try{const r=await api('/api/folders?path='+encodeURIComponent(path));$('#folderNav').innerHTML='<div class="folder-controls"><button data-folder="">음악 폴더</button>'+(path?'<button data-folder="'+esc(path.split('/').slice(0,-1).join('/'))+'">상위 폴더</button>':'')+'</div><p class="browser-note">'+esc(path||'/music')+'</p>';S.artists=r.items;$('#artistList').innerHTML=r.items.map(a=>'<button class="artist-row" data-folder="'+esc(a.id)+'"><span>▸ '+esc(a.name)+'</span></button>').join('');if(path.includes('/')){S.artist={id:'folder:'+path,name:path.split('/').pop(),folder:path};const data=await api('/api/albums?artist='+encodeURIComponent(S.artist.id));S.albums=data.items;$('#albumListTitle').textContent=S.artist.name+' · 앨범';$('#albumCount').textContent=data.items.length+'장';renderAlbums();if(data.truncated)toast('현재 페이지 앨범만 표시합니다. 아티스트 검색으로 범위를 좁혀 주세요.');}}catch(e){toast(e.message)}}
$('#artistList').addEventListener('click',e=>{const b=e.target.closest('[data-folder]');if(b)void browse(b.dataset.folder)});$('#folderNav').addEventListener('click',e=>{const b=e.target.closest('[data-folder]');if(b)void browse(b.dataset.folder)});
function start(){S.sourceMode='NAS_INDEX_READ_ONLY';$('.header-right .demo-pill').textContent='NAS 색인 태그 · 읽기 전용';$('footer span').textContent='NAS 저장 색인 조회 · 실제 파일 재읽기/태그 쓰기 없음';void browse();}

$('#browseToggle').onclick=()=>{const folded=$('.browser').classList.toggle('collapsed');$('#browseToggle').textContent=folded?'펼치기':'접기';$('#browseToggle').setAttribute('aria-expanded',String(!folded))};

import {installTagCoverDraft} from './tag-editor-cover-draft.js';
installTagCoverDraft({getAlbum:()=>S.album,getSelectedFiles:()=>[...S.selected]});
